using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidDiagnosticEvidenceBundle(string Fingerprint,string NativeBuildEvidenceFingerprint,AndroidDiagnosticsSummary Summary,IReadOnlyList<DeviceAcceptanceEvidence> Checks);public static class AndroidDiagnosticEvidenceBundleRules{public static AndroidDiagnosticEvidenceBundle Create(NativeBuildEvidence build,AndroidDiagnosticsSummary summary,IEnumerable<DeviceAcceptanceEvidence> checks){NativeBuildEvidenceRules.Validate(build);var a=checks.OrderBy(x=>x.Scenario,StringComparer.Ordinal).ThenBy(x=>x.EvidenceFingerprint,StringComparer.Ordinal).ToArray();if(a.Any(x=>x.NativeBuildEvidenceFingerprint!=build.EvidenceFingerprint))throw new InvalidOperationException("Diagnostic checks must reference the exact native build.");var text=build.EvidenceFingerprint+"|"+summary.Passed+"|"+summary.Failed+"|"+summary.NotRun+"|"+string.Join("|",a.Select(x=>x.EvidenceFingerprint));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,build.EvidenceFingerprint,summary,a);}}
